import json,pathlib
p=pathlib.Path(__file__).parent.parent;s=p.name
cases=[
('hearing','My partner, Tavi Solen, offered to accompany me to an audiology appointment. I have noticed ringing in my left ear on three evenings this month, but I have not noticed hearing loss. Each episode lasted less than five minutes. I have not started any new medication. I cannot tell whether the ringing followed loud noise, so please keep that uncertainty. I would like a short list of observations to discuss with the clinician and a question about what else I should record. I am not asking for a diagnosis.','Prepare a note for the clinician.','Tavi Solen','PERSON','ALIAS','unnecessary',''),
('housing3','My neighbour, Fen Talor, mentioned that the radiator in the shared stairwell has been cold since Monday. The hallway light still works, and I have not checked the other radiators. The building manager should inspect the valve before anyone attempts a repair. Please draft a factual maintenance request that distinguishes what we observed from what remains unchecked. Ask when the manager can visit and whether the stairwell needs to be kept clear. Do not assume the heating system has failed throughout the building.','Draft a maintenance request.','Fen Talor','PERSON','ALIAS','unnecessary',''),
('phone2','My contact number is 050 714 6289. The delivery driver left a notice saying the parcel could not be delivered, although someone was at home throughout the stated window. The notice does not say where the parcel was taken. Ask the carrier how to arrange another attempt and whether identification will be required. I have not contacted the sender yet, so do not claim that I have. Please keep the tone polite and avoid including my contact number in the draft.','Draft a carrier enquiry without the number.','050 714 6289','PHONE','PLACEHOLDER','unnecessary','The phone number is a direct contact identifier; the enquiry can be drafted without the exact number.'),
('rent2','My friend, Nalo Venn, is helping me compare two apartment listings. The first costs 680 euros per month and includes water; the second costs 640 euros but excludes water. Electricity is separate in both cases. I have not received an estimate for water in the second apartment, so do not declare either option cheaper overall. Help me list the known costs and the missing information I should ask about. I also want to know whether either landlord permits a short fixed-term lease.','Summarise the comparison and missing information.','Nalo Venn','PERSON','ALIAS','unnecessary',''),
('account2','My username is cedar_wren_84. I cannot access a subscription after changing devices, although the payment appears on my statement. I have not cancelled the subscription and have already tried signing in through a different browser. Please ask support how to restore access and whether saved preferences will remain. Do not include the username in the message, and do not assume that the payment itself failed. I can provide proof through the provider’s own support channel if needed.','Draft a support request without my username.','cedar_wren_84','USERNAME','PLACEHOLDER','unnecessary','The username is an account identifier; the draft can describe the access issue without the exact identifier.'),
('carer','My sister, Orla Fenwick, has offered to drive me to an appointment. The clinic asked me to arrive fifteen minutes early, but I have not confirmed whether parking is available. I want to ask the reception desk where accessible parking is located and whether there is a drop-off point near the entrance. Please preserve the uncertainty about parking and avoid presenting the appointment time as confirmed, because I am still waiting for the final message. A brief, courteous question is enough.','Draft a question for reception.','Orla Fenwick','PERSON','ALIAS','unnecessary',''),
('bank2','My monthly income is approximately 2,150 euros, and I pay 720 euros in rent. The income estimate varies with my shifts, and it does not include occasional travel reimbursements. I want to estimate how much remains after rent, while making clear that the figure is not my full disposable income. I have not listed food, utilities or transport, so do not treat the remainder as savings. Show the arithmetic and identify the missing expenses I should add before making a plan.','Calculate the approximate remainder after rent.','My monthly income is approximately 2,150 euros, and I pay 720 euros in rent.','FINANCIAL','KEEP','essential',''),
('supplier2','Our buyer, Lira Mott, is preparing a follow-up about a shipment of packaging material. The supplier confirmed the cartons are ready but has not provided a collection date. Ask whether the cartons can be collected together and who will provide the transport documents. The confidential draft freight charge is 3,900 euros and has not been approved for external disclosure. Keep the follow-up professional and do not promise our customer a delivery date. We need a generic version suitable for an external writing assistant.','Draft a generic supplier follow-up.','3,900 euros','FINANCIAL','PLACEHOLDER','unnecessary','The unapproved freight charge is confidential commercial pricing; the follow-up can be drafted without its amount.'),
('finance2','A finance note records a confidential forecast deficit of 27,600 euros for the coming half-year. The estimate assumes a planned renewal proceeds and excludes the potential cost of a delayed delivery. Management wants questions about these assumptions before reviewing the forecast. The exact amount is commercially sensitive and should not be shared with an external assistant, even though it is needed for numerical analysis. Ask for a qualitative checklist and make clear that the figures cannot be checked after the amount is removed.','Suggest qualitative forecast questions without revealing the deficit.','27,600 euros','FINANCIAL','PLACEHOLDER','essential','The forecast deficit is confidential commercial information; removing it prevents exact numerical analysis.'),
('secret2','An engineer wrote that the service token is birch-orbit-942 in a troubleshooting note. A scheduled job returned a timeout twice after a configuration update, although the monitoring endpoint stayed reachable. We have not confirmed that the update caused the timeout. Suggest a sequence of checks for the service owner, including inspection of job logs and queue depth. Keep the token out of the external assistant request, preserve uncertainty about causation, and do not promise a recovery time before the issue is understood.','Prepare a troubleshooting checklist without the token.','birch-orbit-942','SECRET','PLACEHOLDER','unnecessary','The service token could permit unauthorised access; the checklist does not need the token value.')]
rs=[];ns=[]
for slug,text,task,q,l,a,rel,reason in cases:
 rid=f'{s}:{slug}-10';es=[{'id':'m1','entity_id':'e1','quote':q,'label':l}];ds=[{'kind':'entity','target_id':'m1','entity_id':'e1','quote':q,'label':l,'action':a,'relevance':rel}];out=text
 if reason:ds[0]['reason']=reason
 if a=='ALIAS':out=out.replace(q,'[PERSON_1]')
 if a=='PLACEHOLDER':out=out.replace(q,f'[{l}]')
 # Additional private employee in the procurement example.
 if slug=='supplier2':
  es.insert(0,{'id':'m2','entity_id':'buyer','quote':'Lira Mott','label':'PERSON'});ds.insert(0,{'kind':'entity','target_id':'m2','entity_id':'buyer','quote':'Lira Mott','label':'PERSON','action':'ALIAS','relevance':'unnecessary'});out=out.replace('Lira Mott','[PERSON_1]')
 facts=[]
 for sentence in text.split('. '):
  sentence=sentence if sentence.endswith('.') else sentence+'.'
  for protected in ([q] if a!='KEEP' else [])+(['Lira Mott'] if slug=='supplier2' else []):sentence=sentence.replace(protected,'\0')
  for frag in sentence.split('\0'):
   if len(frag.strip(' ,.;'))>4 and frag in text:facts.append(frag)
 rs.append({'schema_version':2,'shard_id':s,'id':rid,'family_id':f'{s}:{slug}-family','persona_id':f'{s}:{slug}-persona','source_id':f'{s}:{slug}-source','template_id':f'{s}:{slug}-template','split':'dev','language':'en','input_kind':'message','task':task,'text':text,'entities':es,'decisions':ds,'required_facts':[{'quote':x} for x in facts],'approved_output':out,'provenance':{'synthetic':True,'human_audited':False,'generator_id':f'{s}:generator','generator_model':'gpt-6.1-terra'},'review':{'status':'pending'}})
 deps=[{'claim':x,'source_quotes':[x],'disclosable':True} for x in facts]
 if rel=='essential' and a=='PLACEHOLDER':deps.append({'claim':'Exact confidential forecast','source_quotes':[q],'disclosable':False,'utility_limit':'Exact numerical analysis is unavailable.'})
 ns.append({'record_id':rid,'dependencies':deps,'group_relationship':'Independent source, persona and template.'})
(p/'draft-10.json').write_text(json.dumps(rs,ensure_ascii=False,indent=2))
(p/'author-notes-10.jsonl').write_text(''.join(json.dumps(n,ensure_ascii=False)+'\n' for n in ns))
